import flask
from flask import request, jsonify
import subprocess
import os
import re

app = flask.Flask(__name__)

# Configuration for build system
BUILD_WORKSPACE = os.environ.get('BUILD_WORKSPACE', '/tmp/builds')
ALLOWED_REPOS = os.environ.get('ALLOWED_REPOS', 'github.com/internal')

def sanitize_branch(branch):
    """Basic sanitization - only allow alphanumeric, dash, slash, dot, underscore"""
    if not re.match(r'^[a-zA-Z0-9._/\-]+$', branch):
        return None
    return branch

def validate_repo_url(url):
    """Ensure repo URL is from allowed domain"""
    # Note: this only checks prefix, not full URL structure
    allowed = ALLOWED_REPOS.split(',')
    for repo in allowed:
        if repo.strip() in url:
            return True
    return False

@app.route('/api/v1/build', methods=['POST'])
def trigger_build():
    """Trigger a build for a given repository and branch"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    repo_url = data.get('repo_url', '')
    branch = data.get('branch', 'main')
    build_args = data.get('build_args', '')

    if not validate_repo_url(repo_url):
        return jsonify({'error': 'repository not in allowlist'}), 403

    branch = sanitize_branch(branch)
    if not branch:
        return jsonify({'error': 'invalid branch name'}), 400

    # Create workspace
    workspace = os.path.join(BUILD_WORKSPACE, f'build_{os.getpid()}')
    os.makedirs(workspace, exist_ok=True)

    try:
        # Clone the repository
        clone_cmd = f'git clone --depth 1 --branch {branch} https://{repo_url} {workspace}/src'
        result = subprocess.run(clone_cmd, shell=True, capture_output=True, timeout=60, text=True)

        if result.returncode != 0:
            return jsonify({'error': 'clone failed', 'details': result.stderr}), 500

        # Run build with user-provided arguments
        # build_args is passed to make for custom build targets/variables
        build_cmd = f'cd {workspace}/src && make build {build_args}'
        result = subprocess.run(build_cmd, shell=True, capture_output=True, timeout=300, text=True)

        return jsonify({
            'status': 'completed',
            'stdout': result.stdout[-2000:],
            'stderr': result.stderr[-2000:],
            'exit_code': result.returncode
        })

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'build timeout'}), 504
    finally:
        subprocess.run(f'rm -rf {workspace}', shell=True)

@app.route('/api/v1/status', methods=['GET'])
def status():
    return jsonify({'status': 'ok', 'workspace': BUILD_WORKSPACE})

@app.route('/api/v1/artifacts', methods=['GET'])
def list_artifacts():
    """List build artifacts - useful for debugging"""
    path = request.args.get('path', BUILD_WORKSPACE)
    # Prevent directory traversal in artifact listing
    real_path = os.path.realpath(path)
    if not real_path.startswith(os.path.realpath(BUILD_WORKSPACE)):
        return jsonify({'error': 'access denied'}), 403
    try:
        files = os.listdir(real_path)
        return jsonify({'files': files})
    except OSError:
        return jsonify({'files': []})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
